## 3. Inbound Adapter: Legacy Module

**Location:** `/Users/admin/project/integrated-search/inbound-adapter/legacy/`

Responsible for Kafka CDC event consumption and mapping to domain models.

### 3.1 Configuration Files

#### LegacyReserveSyncConsumerProperties.kt
```kotlin
@ConfigurationProperties(prefix = "legacy-sync-consumer")
data class LegacyReserveSyncConsumerProperties(
    val productCdc: DynamicIndexConsumer,
) {
    data class DynamicIndexConsumer(
        val bootstrapServers: String,
        val topic: String,
        val groupId: String,
        val concurrency: Int = 1,
        val idleEventInterval: Long = 100L, // ms
        val properties: ConsumerProperties,
    ) {
        data class ConsumerProperties(
            val autoOffsetReset: String,
            val enableAutoCommit: Boolean,
            val maxPollRecords: Int = 1000,
            val fetchMaxWaitMs: Int = 5000,
            val fetchMinSize: Int = 1024768,
            val sessionTimeoutMs: Int = 30000,
            val heartbeatIntervalMs: Int = 10000,
            val securityProtocol: String? = null,
