@Component
class LegacyApiClient(
    @field:Qualifier("LegacyWebClient")
    private val client: WebClient,
) {
    private val logger by logger()

    suspend fun pushQueue(
        service: String,
        method: HttpMethod,
        body: Any,
    ) {
        try {
            client
                .method(method)
                .uri("/pushQueue.json?service={service}", service)
                .contentType(MediaType.APPLICATION_JSON)
                .bodyValue(body)
                .retrieve()
                .bodyToMono<String>()
                .awaitSingle()
        } catch (ex: Exception) {
            logger.error { "Legacy API pushQueue 호출 실패 [service=$service]: $ex" }
            throw ex
        }
    }
}
```

**Endpoint Details:**
