package com.cowave.search.application.index.service

import com.cowave.search.application.index.dto.DependencyId
import com.cowave.search.application.index.dto.LinkedProductRequest
import com.cowave.search.application.index.dto.UnlinkedProductDeleteRequest
import com.cowave.search.application.index.dto.UnlinkedProductRequest
import com.cowave.search.application.index.mapper.LegacySyncMapper
import com.cowave.search.application.index.repository.LegacyReserveSyncRepository
import com.cowave.search.application.index.service.proxy.CachedProxyApplicationService
import com.cowave.search.domain.index.dto.ChangedData
import com.cowave.search.domain.index.dto.LegacyProductData
import com.cowave.search.domain.index.enums.Operation
import com.cowave.search.domain.proxy.category.CategoryProjection
import com.cowave.search.domain.proxy.mall.MallProjection
import com.cowave.shared.utils.logger
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.supervisorScope
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty
import org.springframework.stereotype.Service

@Service
@ConditionalOnProperty(name = ["legacy-sync.enabled"], havingValue = "true", matchIfMissing = false)
class LegacyReserveSyncApplicationService(
    private val legacyReserveSyncRepository: LegacyReserveSyncRepository,
    private val cachedProxyApplicationService: CachedProxyApplicationService,
) {
    private val logger by logger()

    fun syncToLegacy(changedData: List<ChangedData<LegacyProductData>>) {
        if (changedData.isEmpty()) return

        val dependencyId = getDependencyId(changedData)
        val dependency = cachedProxyApplicationService.fetchDependencies(dependencyId)

        runBlocking(Dispatchers.IO) {
            // push 태스크 수집 → supervisorScope로 병렬 실행 (개별 실패 격리)
            val pushTasks = buildPushTasks(changedData, dependency.categories, dependency.malls)

            if (pushTasks.isNotEmpty()) {
                supervisorScope {
                    pushTasks
                        .map { task ->
                            async {
                                runCatching { task() }
                                    .onFailure { ex -> logger.error(ex) { "Legacy push 실패" } }
                            }
                        }.awaitAll()
                }
            }
        }
    }

    private fun buildPushTasks(
        changedData: List<ChangedData<LegacyProductData>>,
        categories: Map<Int, CategoryProjection>,
        malls: Map<Int, MallProjection>,
    ): List<suspend () -> Unit> {
        val pushTasks = mutableListOf<suspend () -> Unit>()
        val grouped = changedData.groupBy { it.op }

        grouped.forEach { (op, items) ->
            val linked = mutableListOf<LinkedProductRequest>()
            val unlinked = mutableListOf<UnlinkedProductRequest>()
            val unlinkedDeletes = mutableListOf<UnlinkedProductDeleteRequest>()

            items.forEach items@{ item ->
                val data = if (op == Operation.DELETE) item.beforeData else item.afterData
                if (data == null) {
                    logger.warn { "Legacy sync skipped: no data for product id=${item.id}, op=$op" }
                    return@items
                }

                val mall = malls[data.shopId]

                when {
                    data.isCatalogMatch -> {
                        linked.add(LegacySyncMapper.convertToLinkedRequest(data, mall))
                    }

                    op == Operation.DELETE -> {
                        unlinkedDeletes.add(LegacySyncMapper.convertToUnlinkedDeleteRequest(data, mall))
                    }

                    else -> {
                        val category = categories[data.categoryId]
                        unlinked.add(LegacySyncMapper.convertToUnlinkedRequest(data, category, mall))
                    }
                }
            }

            if (linked.isNotEmpty()) pushTasks.add { legacyReserveSyncRepository.pushLinkedProducts(linked, op) }
            if (unlinked.isNotEmpty()) pushTasks.add { legacyReserveSyncRepository.pushUnlinkedProducts(unlinked, op) }
            if (unlinkedDeletes.isNotEmpty()) {
                pushTasks.add {
                    legacyReserveSyncRepository.pushUnlinkedProductDeletes(
                        unlinkedDeletes,
                    )
                }
            }
        }

        return pushTasks
    }

    fun getDependencyId(documents: List<ChangedData<LegacyProductData>>): DependencyId {
        val categoryIds: MutableList<Int> = mutableListOf()
        val mallIds: MutableList<Int> = mutableListOf()

        documents.forEach {
            it.afterData?.categoryId?.run { categoryIds.add(this) }
            it.afterData?.shopId?.run { mallIds.add(this) }
        }

        return DependencyId(
            categoryIds = categoryIds.distinct(),
            mallIds = mallIds.distinct(),
        )
    }
}

package com.cowave.search.inbound_adapter.legacy.listener

import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ProductCdcEnvelope
import com.cowave.search.application.index.mapper.LegacySyncMapper
import com.cowave.search.application.index.service.LegacyReserveSyncApplicationService
import com.cowave.search.domain.index.policy.ProductMergeStrategy
import com.cowave.search.inbound_adapter.legacy.mapper.toChangedProductData
import com.cowave.shared.utils.logger
import org.apache.avro.specific.SpecificRecord
import org.apache.kafka.clients.consumer.Consumer
import org.apache.kafka.clients.consumer.ConsumerRecord
import org.springframework.kafka.listener.BatchAcknowledgingConsumerAwareMessageListener
import org.springframework.kafka.support.Acknowledgment

class LegacyReserveSyncListener(
    private val legacyReserveSyncApplicationService: LegacyReserveSyncApplicationService,
) : BatchAcknowledgingConsumerAwareMessageListener<SpecificRecord, SpecificRecord> {
    private val logger by logger()

    override fun onMessage(
        data: List<ConsumerRecord<SpecificRecord, SpecificRecord>>,
        acknowledgment: Acknowledgment?,
        consumer: Consumer<*, *>,
    ) {
        runCatching {
            val changedDocuments =
                data
                    .filter { record ->
                        val envelope = record.value() as ProductCdcEnvelope
                        val product = envelope.after ?: envelope.before
                        product != null && product.categoryId > 0
                    }.map { it.toChangedProductData() }

            val mergedDocuments = ProductMergeStrategy.merge(changedDocuments)
            legacyReserveSyncApplicationService.syncToLegacy(LegacySyncMapper.convertToChangedLegacyData(mergedDocuments))
        }.onSuccess {
            acknowledgment?.acknowledge()
        }.onFailure { ex ->
            logger.error(ex) { "Failed to sync products to legacy" }
        }.getOrThrow()
    }
}

package com.cowave.search.application.index.service.proxy

import com.cowave.search.application.index.dto.Dependency
import com.cowave.search.application.index.dto.DependencyId
import org.springframework.beans.factory.annotation.Qualifier
import org.springframework.stereotype.Service
import java.util.concurrent.CompletableFuture
import java.util.concurrent.Executor

@Service
class CachedProxyApplicationService(
    private val categoryApplicationService: CategoryApplicationService,
    private val brandApplicationService: BrandApplicationService,
    private val manufacturerApplicationService: ManufacturerApplicationService,
    private val mallApplicationService: MallApplicationService,
    @param:Qualifier("IOExecutor") private val ioExecutor: Executor,
) {
    fun fetchDependencies(dependencyId: DependencyId): Dependency {
        val categoryFuture = async(dependencyId.categoryIds, categoryApplicationService::getCachedAllByIds)
        val brandFuture = async(dependencyId.brandIds, brandApplicationService::getCachedAllByIds)
        val manufacturerFuture = async(dependencyId.manufacturerIds, manufacturerApplicationService::getCachedAllByIds)
        val mallFuture = async(dependencyId.mallIds, mallApplicationService::getCachedAllByIds)
        CompletableFuture.allOf(categoryFuture, brandFuture, manufacturerFuture, mallFuture).join()

        return Dependency(
            categories = categoryFuture.join(),
            brands = brandFuture.join(),
            manufacturers = manufacturerFuture.join(),
            malls = mallFuture.join(),
        )
    }

    private fun <K, V> async(
        ids: List<K>,
        fetch: (List<K>) -> Map<K, V>,
    ): CompletableFuture<Map<K, V>> =
        if (ids.isEmpty()) {
            CompletableFuture.completedFuture(emptyMap())
        } else {
            CompletableFuture.supplyAsync({ fetch(ids) }, ioExecutor)
        }
}

package com.cowave.search.client.legacy_api

import com.cowave.shared.utils.logger
import kotlinx.coroutines.reactor.awaitSingle
import org.springframework.beans.factory.annotation.Qualifier
import org.springframework.http.HttpMethod
import org.springframework.http.MediaType
import org.springframework.stereotype.Component
import org.springframework.web.reactive.function.client.WebClient
import org.springframework.web.reactive.function.client.bodyToMono

@Component
class LegacyApiClient(
    @field:Qualifier("LegacyWebClient")
    private val client: WebClient,
) {
    private val logger by logger()

    suspend fun pushQueue(
        service: String,
        method: HttpMethod,
        body: Any,
    ) {
        try {
            client
                .method(method)
                .uri("/pushQueue.json?service={service}", service)
                .contentType(MediaType.APPLICATION_JSON)
                .bodyValue(body)
                .retrieve()
                .bodyToMono<String>()
                .awaitSingle()
        } catch (ex: Exception) {
            logger.error { "Legacy API pushQueue 호출 실패 [service=$service]: $ex" }
            throw ex
        }
    }
}
